mapper.insert:
insert into workout_records(
    user_id, course_id, duration_minutes, completion_percent, started_at, completed_at
)
values (
    #{userId}, #{courseId}, #{durationMinutes}, #{completionPercent}, #{startedAt}, #{completedAt}
)

insert into custom_workout_records(
    user_id, custom_course_id, duration_minutes, completion_percent, started_at, completed_at
)
values (
    #{userId}, #{customCourseId}, #{durationMinutes}, #{completionPercent}, #{startedAt}, #{completedAt}
)

mapper.select:
select count(*)
from custom_courses
where id = #{courseId} and user_id = #{userId}

select count(*) completed_count, coalesce(sum(duration_minutes), 0) total_minutes
from (
    select duration_minutes, completion_percent from workout_records where user_id = #{userId}
    union all
    select duration_minutes, completion_percent from custom_workout_records where user_id = #{userId}
) history
where completion_percent >= 80

select distinct cast(completed_at as date) completed_date
from (
    select completed_at, completion_percent from workout_records where user_id = #{userId}
    union all
    select completed_at, completion_percent from custom_workout_records where user_id = #{userId}
) history
where completion_percent >= 80
order by completed_date desc
